mapper.update:
UPDATE housekeeper_schedule
schedule_date = #{scheduleDate}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser}
WHERE id = #{id}

mapper.select:
SELECT s.id, s.housekeeper_id, h.name AS housekeeper_name, s.schedule_date, s.start_time, s.end_time, s.status, s.create_user, s.update_user, s.create_time, s.update_time FROM housekeeper_schedule s LEFT JOIN housekeeper h ON s.housekeeper_id = h.id
AND s.housekeeper_id = #{housekeeperId}
AND s.schedule_date = #{scheduleDate}
ORDER BY s.schedule_date ASC, s.start_time ASC
